// Code generated from the game's port/linux/src/port_config.c (its
// server.* and network.* entries) and docs/dedicated_server.md (the choices
// and ranges); edit by hand when the game's settings change.

package spec

// Settings is the game settings a profile sets: those the server changes
// live (sv_set, PUT /api/settings: Live) and those it reads at its start.
// The fleet's own (ports, binds, passwords, the publisher key, the log's
// format, updates) are not here: they are the environment's (Env).
var Settings = []Setting{
	{Name: "server.name", Type: "string", Default: "OpenCE Server", Env: "HALO_SERVER_NAME", Live: true, Group: "Game", Comment: "The game's name in the lobby and the server browser: 15 characters of printable ASCII."},
	{Name: "server.max_players", Type: "integer", Default: 16, Env: "HALO_SERVER_MAX_PLAYERS", Live: true, Group: "Game", Min: ptr(2), Max: ptr(127), Comment: "The most players (2 to 127)."},
	{Name: "server.min_players", Type: "integer", Default: 1, Env: "HALO_SERVER_MIN_PLAYERS", Live: true, Group: "Game", Min: ptr(1), Max: ptr(16), Comment: "Players in the lobby before it counts down to a game (1 to 16)."},
	{Name: "server.password", Type: "string", Default: "", Env: "HALO_SERVER_PASSWORD", Live: true, Group: "Game", Secret: true, Comment: "The password the server browser asks for (the invite link still joins); empty for none. Never logged."},
	{Name: "server.public", Type: "boolean", Default: true, Env: "HALO_SERVER_PUBLIC", Live: true, Group: "Listing", Comment: "List the server in everyone's server browser (on the master servers, with network.online); false: joined by its invite link and on the LAN."},
	{Name: "server.rotation_fallback", Type: "boolean", Default: false, Env: "HALO_SERVER_ROTATION_FALLBACK", Live: true, Group: "Rotation", Comment: "With no playable rotation entry, play bloodgulch:slayer rather than stop (exit code 3)."},
	{Name: "server.lobby_seconds", Type: "integer", Default: 15, Env: "HALO_SERVER_LOBBY_SECONDS", Live: true, Group: "Timings", Min: ptr(0), Max: ptr(300), Comment: "Seconds the lobby counts down once min_players are in (0 to 300; 0 starts at once)."},
	{Name: "server.postgame_seconds", Type: "integer", Default: 12, Env: "HALO_SERVER_POSTGAME_SECONDS", Live: true, Group: "Timings", Min: ptr(0), Max: ptr(300), Comment: "Seconds the scores show after a game (0 to 300)."},
	{Name: "server.empty_seconds", Type: "integer", Default: 30, Env: "HALO_SERVER_EMPTY_SECONDS", Live: true, Group: "Timings", Min: ptr(0), Comment: "Seconds a game nobody is in goes on before it ends (0: never). A game whose last player leaves ends at once, as the game ends it."},
	{Name: "server.idle_minutes", Type: "integer", Default: 0, Env: "HALO_SERVER_IDLE_MINUTES", Live: true, Group: "Timings", Min: ptr(0), Comment: "Minutes a game goes on with no score before it ends (0: never)."},
	{Name: "server.team_start", Type: "string", Default: "one", Env: "HALO_SERVER_TEAM_START", Live: true, Group: "Game", Choices: []string{"one", "both", "skip"}, Comment: "A team game: \"one\" starts with one team's players (the next joiners balance), \"both\" waits for a player on each team, \"skip\" skips team games while one player waits."},
	{Name: "server.motd", Type: "string", Default: "", Env: "HALO_SERVER_MOTD", Live: true, Group: "Game", Comment: "A notice each machine is shown as it joins (127 characters); empty for none."},
	{Name: "server.frame_rate", Type: "integer", Default: 60, Env: "HALO_SERVER_FRAME_RATE", Live: true, Group: "Performance", Min: ptr(30), Max: ptr(120), Comment: "Frames a second (30 to 120); the game's ticks stay 30 a second. A server with no other machine runs 10."},
	{Name: "server.afk_kick_minutes", Type: "integer", Default: 5, Env: "HALO_SERVER_AFK_KICK_MINUTES", Live: true, Group: "Game", Min: ptr(0), Max: ptr(60), Comment: "The minutes a player may be away from the controls in a game (no button, stick, trigger or turn of the view) before being kicked, told a minute before (0: never; up to 60). The lobby, the postgame, cinematics and time dead do not count."},
	{Name: "server.afk_kick_when_full", Type: "boolean", Default: false, Env: "HALO_SERVER_AFK_KICK_WHEN_FULL", Live: true, Group: "Game", Comment: "Kick players away only while the game is full, after afk_kick_full_minutes."},
	{Name: "server.afk_kick_full_minutes", Type: "integer", Default: 3, Env: "HALO_SERVER_AFK_KICK_FULL_MINUTES", Live: true, Group: "Game", Min: ptr(2), Max: ptr(60), Comment: "With afk_kick_when_full, the minutes away before a kick (2 to 60)."},
	{Name: "server.map_vote", Type: "boolean", Default: false, Env: "HALO_SERVER_MAP_VOTE", Live: true, Group: "Rotation", Comment: "As the lobby opens after a game, the players vote for the next game among map_vote_choices entries of the rotation picked at random (not the one just played), on a screen of their lobby; the rotation goes on after the winner."},
	{Name: "server.map_vote_choices", Type: "integer", Default: 4, Env: "HALO_SERVER_MAP_VOTE_CHOICES", Live: true, Group: "Rotation", Min: ptr(2), Max: ptr(8), Comment: "The entries a map vote offers (2 to 8)."},
	{Name: "server.map_vote_seconds", Type: "integer", Default: 20, Env: "HALO_SERVER_MAP_VOTE_SECONDS", Live: true, Group: "Rotation", Min: ptr(5), Max: ptr(120), Comment: "How long a map vote runs (5 to 120 seconds); it ends sooner once every player has voted."},
	{Name: "server.coop_difficulty", Type: "string", Default: "normal", Env: "HALO_SERVER_COOP_DIFFICULTY", Live: true, Group: "Co-op", Choices: []string{"easy", "normal", "hard", "impossible"}, Comment: "Co-op rotation entries' (<level>:coop) difficulty: \"easy\", \"normal\", \"hard\" or \"impossible\"."},
	{Name: "server.coop_bsp_switch", Type: "string", Default: "majority", Env: "HALO_SERVER_COOP_BSP_SWITCH", Live: true, Group: "Co-op", Choices: []string{"majority", "anyone"}, Comment: "A co-op loading zone: \"majority\", it moves the team on once more than half of the living players who are not away stand in zones to the same place (the others are told how many more must cross); \"anyone\", the first player in one. A mission script's switch is not held."},
	{Name: "server.coop_bsp_switch_cooldown_seconds", Type: "integer", Default: 15, Env: "HALO_SERVER_COOP_BSP_SWITCH_COOLDOWN_SECONDS", Live: true, Group: "Co-op", Min: ptr(0), Max: ptr(300), Comment: "The seconds after a loading zone moved the team on before another may (0 to 300)."},
	{Name: "server.master_publish", Type: "boolean", Default: true, Env: "HALO_SERVER_MASTER_PUBLISH", Live: true, Group: "Listing", Comment: "Publish a public server to the official master servers, signed with the publisher key (publisher_key_file)."},
	{Name: "network.text_chat", Type: "string", Default: "on", Env: "HALO_NET_TEXT_CHAT", Live: true, Group: "Safety", Choices: []string{"on", "links", "off"}, Comment: "Hosting: the text chat: \"on\" (links in lines are refused), \"links\" (links allowed) or \"off\", in either case. Always off in a game a player hosts that is listed in the server browser (a public internet game); a dedicated server's follows this setting, listed or not."},
	{Name: "server.chat_filter", Type: "string", Default: "off", Env: "HALO_SERVER_CHAT_FILTER", Live: true, Group: "Safety", Choices: []string{"off", "censor", "block"}, Comment: "The words the server keeps out of its chat and its players' names (streamer mode's list, by the groups below): \"off\"; \"censor\", a line's words shown as stars; \"block\", a line with them not sent (its sender is told why) and a player whose name has them refused as they join. Links are the text chat's."},
	{Name: "server.chat_filter_slurs", Type: "string", Default: "mild", Env: "HALO_SERVER_CHAT_FILTER_SLURS", Live: true, Group: "Safety", Choices: []string{"off", "severe", "strong", "mild"}, Comment: "With the word filter on, the slurs it keeps out: \"off\", \"severe\" (the worst), \"strong\" or \"mild\" (all of them)."},
	{Name: "server.chat_filter_swearing", Type: "string", Default: "off", Env: "HALO_SERVER_CHAT_FILTER_SWEARING", Live: true, Group: "Safety", Choices: []string{"off", "severe", "strong", "mild"}, Comment: "With the word filter on, the swearing it keeps out: \"off\", \"severe\" (the worst), \"strong\" or \"mild\" (all of it)."},
	{Name: "server.chat_filter_insults", Type: "string", Default: "off", Env: "HALO_SERVER_CHAT_FILTER_INSULTS", Live: true, Group: "Safety", Choices: []string{"off", "severe", "strong", "mild"}, Comment: "With the word filter on, the insults it keeps out: \"off\", \"severe\" (the worst), \"strong\" or \"mild\" (all of them)."},
	{Name: "server.vpn_policy", Type: "string", Default: "link", Env: "HALO_SERVER_VPN_POLICY", Live: true, Group: "Safety", Choices: []string{"off", "link", "block"}, Comment: "A machine that joins from a VPN's, a Tor exit's or a datacenter's address (the master servers' netlist): \"link\", refused unless it shows a pass of a Discord account linked at a master this server publishes to (an updated game shows one by itself); \"block\", refused, pass or not; \"off\", let in."},
	{Name: "server.vpn_fail", Type: "string", Default: "open", Env: "HALO_SERVER_VPN_FAIL", Live: true, Group: "Safety", Choices: []string{"open", "closed"}, Comment: "Until the server holds a netlist (its masters', or server.vpn_list's): \"open\" lets every machine in; \"closed\" refuses those from the internet as \"block\" would."},
	{Name: "server.vpn_list", Type: "string", Default: "", Env: "HALO_SERVER_VPN_LIST", Live: false, Group: "Safety", Comment: "A netlist file to read instead of the masters' (a full path, or beside config.toml), for a server that publishes nowhere, or a test; empty: the masters'. Read at the start and by sv_reload."},
	{Name: "server.vpn_check_lan", Type: "boolean", Default: false, Env: "HALO_SERVER_VPN_CHECK_LAN", Live: true, Group: "Safety", Comment: "Check the LAN's machines against the VPN lists too (for tests); otherwise only a machine's real internet address is checked."},
	{Name: "server.link_min_age_days", Type: "integer", Default: 365, Env: "HALO_SERVER_LINK_MIN_AGE_DAYS", Live: true, Group: "Safety", Min: ptr(0), Max: ptr(3650), Comment: "With a pass, the youngest Discord account let in over a VPN, in days from the account's id (0 to 3650; 365: a year)."},
	{Name: "server.link_one_seat", Type: "boolean", Default: true, Env: "HALO_SERVER_LINK_ONE_SEAT", Live: true, Group: "Safety", Comment: "With a pass, refuse a second machine of a Discord account already in the game."},
	{Name: "server.max_machines_per_address", Type: "integer", Default: 0, Env: "HALO_SERVER_MAX_MACHINES_PER_ADDRESS", Live: true, Group: "Safety", Min: ptr(0), Max: ptr(128), Comment: "The machines of one address (an internet play peer's real one) that may play at once; one more is refused (0: no limit)."},
	{Name: "network.voice_lobby", Type: "boolean", Default: true, Env: "HALO_NET_VOICE_LOBBY", Live: true, Group: "Voice", Comment: "Hosting: voice chat in the lobby, before and after a game, where every player hears every other."},
	{Name: "network.voice_mode", Type: "string", Default: "team_global_enemy_proximity", Env: "HALO_NET_VOICE_MODE", Live: true, Group: "Voice", Choices: []string{"off", "team_proximity", "team_enemy_proximity", "team_global", "team_global_enemy_proximity"}, Comment: "Hosting: voice chat in a game: \"off\"; \"team_proximity\" (teammates near); \"team_enemy_proximity\" (anyone near); \"team_global\" (all teammates); or \"team_global_enemy_proximity\" (all teammates, and enemies near). A game without teams has only enemies; co-op only teammates."},
	{Name: "network.voice_kbps", Type: "integer", Default: 24, Env: "HALO_NET_VOICE_KBPS", Live: true, Group: "Voice", Min: ptr(8), Max: ptr(64), Comment: "Hosting: the voices' quality, in the lobby and in a game, in kilobits a second (8 to 64)."},
	{Name: "network.votekick", Type: "boolean", Default: true, Env: "HALO_NET_VOTEKICK", Live: true, Group: "Votes", Comment: "Hosting: let the players vote to kick a player (the scoreboard's right-click, or the console's votekick; F1 or the D-pad's left votes yes, F2 or its right no). The yes votes needed are votekick_threshold's, counted once per address, and more yes than no."},
	{Name: "network.votekick_threshold", Type: "string", Default: "dynamic", Env: "HALO_NET_VOTEKICK_THRESHOLD", Live: true, Group: "Votes", Choices: []string{"dynamic", "static"}, Comment: "Hosting: the yes votes a vote (to kick, to end the game) needs, of the players who may vote: \"dynamic\", scaled with the players (more than half up to 8, 40% up to 32, 30% beyond); \"static\", votekick_percent of them. At least 2 either way."},
	{Name: "network.votekick_percent", Type: "integer", Default: 50, Env: "HALO_NET_VOTEKICK_PERCENT", Live: true, Group: "Votes", Min: ptr(1), Max: ptr(100), Comment: "Hosting: with a static threshold, the percentage of the players who may vote whose yes passes a vote (1 to 100, rounded up)."},
	{Name: "network.vote_end_game", Type: "boolean", Default: true, Env: "HALO_NET_VOTE_END_GAME", Live: true, Group: "Votes", Comment: "Hosting: let the players vote to end the game (\"!endgame\" in the chat; F1 votes yes, F2 no), counted as a vote to kick. The game ends with its scores, as sv_end_game ends it."},
	{Name: "network.votekick_minutes", Type: "integer", Default: 5, Env: "HALO_NET_VOTEKICK_MINUTES", Live: true, Group: "Votes", Min: ptr(0), Max: ptr(60), Comment: "Hosting: the minutes a player must have played on this server to start a vote to kick (0 to 60); to vote, 2 minutes or this, the less."},
	{Name: "network.votekick_ban_minutes", Type: "integer", Default: 30, Env: "HALO_NET_VOTEKICK_BAN_MINUTES", Live: true, Group: "Votes", Min: ptr(1), Max: ptr(1440), Comment: "Hosting: the minutes a player kicked by a vote cannot join again (1 to 1440)."},
	{Name: "network.map_share", Type: "boolean", Default: true, Env: "HALO_NET_MAP_SHARE", Live: true, Group: "Map sharing", Comment: "Hosting: send a player who joins without the game's Custom Edition map the map (from custom_maps), and the resource maps it needs that the player lacks (bitmaps.map, sounds.map, loc.map). The game's other players help (network.map_seed)."},
	{Name: "network.map_share_upload", Type: "integer", Default: 1024, Env: "HALO_NET_MAP_SHARE_UPLOAD", Live: true, Group: "Map sharing", Min: ptr(16), Max: ptr(20480), Comment: "Hosting: the most kilobytes a second the host sends of maps (16 to 20480: 20 MB/s), so that the game's own traffic keeps the rest of the upload."},
	{Name: "network.coop_friendly_fire", Type: "string", Default: "on", Env: "HALO_NET_COOP_FRIENDLY_FIRE", Live: true, Group: "Co-op", Choices: []string{"off", "on", "shields_only", "explosives_only"}, Comment: "Whether the players of an online co-op game hurt each other: \"off\", \"on\", \"shields_only\" or \"explosives_only\" (FRIENDLY FIRE in co-op's Server Setup > Co-op Options writes its choice here). Their AI allies they hurt as network.coop_ally_friendly_fire says."},
	{Name: "network.coop_player_collisions", Type: "boolean", Default: true, Env: "HALO_NET_COOP_PLAYER_COLLISIONS", Live: true, Group: "Co-op", Comment: "Whether the players of an online co-op game bump into each other; false, they walk through each other (the AI's characters they still bump into). PLAYER COLLISIONS in co-op's Server Setup > Co-op Options writes its choice here."},
	{Name: "network.coop_ally_friendly_fire", Type: "boolean", Default: true, Env: "HALO_NET_COOP_ALLY_FRIENDLY_FIRE", Live: true, Group: "Co-op", Comment: "Whether the players of an online co-op game hurt their AI allies (the Marines, Captain Keyes, the Sentinels while they are allies), as in the campaign; false, the players' weapons, grenades and vehicles do them no harm. ALLY FRIENDLY FIRE in co-op's Server Setup > Co-op Options writes its choice here."},
	{Name: "network.shield_effects", Type: "string", Default: "stock", Env: "HALO_NET_SHIELD_EFFECTS", Live: true, Group: "Network", Choices: []string{"stock", "glow", "light_show", "overshield", "glow_overshield", "light_show_overshield", "players"}, Comment: "Host: the shield effects every player of a network game sees, whatever their own: \"stock\", \"glow\", \"light_show\", \"overshield\", \"glow_overshield\" or \"light_show_overshield\" (display.shield_glow, its light_show intensity, display.overshield_effect); \"players\": not synced, each player sees their own settings'. SHIELD EFFECTS in Server Setup > Player Options writes its choice here."},
	{Name: "network.voice_proximity", Type: "real", Default: 15.0, Env: "HALO_NET_VOICE_PROXIMITY", Live: false, Group: "Voice", Comment: "Hosting: how near (world units: 1 is about 3 metres) a player must be to be heard by proximity voice chat (5 to 100)."},
	{Name: "network.coop_own_friendly_fire", Type: "boolean", Default: true, Env: "HALO_NET_COOP_OWN_FRIENDLY_FIRE", Live: false, Group: "Co-op", Comment: "Whether this machine's players hurt, and are hurt by, the other players of an online co-op game: two players hurt each other only if both have it true. FRIENDLY FIRE in that game's pause menu writes its choice here. A player away from the controls for over 70 seconds is hurt by every player, whatever either chose."},
	{Name: "network.coop_enemies_mode", Type: "string", Default: "per_player", Env: "HALO_NET_COOP_ENEMIES_MODE", Live: false, Group: "Co-op", Comment: "Online co-op's extra enemies: \"none\", \"per_player\" (each squad of enemies grows by coop_enemies for each player past the first) or \"multiplier\" (each is coop_enemies_multiplier times as large, for any number of players). EXTRA ENEMIES in co-op's Server Setup > Co-op Options writes its choice here."},
	{Name: "network.coop_pickups", Type: "string", Default: "none", Env: "HALO_NET_COOP_PICKUPS", Live: false, Group: "Co-op", Comment: "Extra campaign weapons, grenades, health kits, overshields and camouflage. Modes: \"none\", \"per_player\" (coop_enemies percent per extra player), or \"multiplier\" (coop_enemies_multiplier times as many), up to 8 times the original pickups. Only safe nearby places receive copies."},
	{Name: "network.coop_vehicles", Type: "string", Default: "none", Env: "HALO_NET_COOP_VEHICLES", Live: false, Group: "Co-op", Comment: "Extra campaign vehicles: \"none\", \"per_player\" or \"multiplier\". After a player clears its unloaded starting place by both bounding radii plus 15 percent, make one more there, up to floor((players - 1) * coop_enemies * 2 / 300) extras, or floor((coop_enemies_multiplier - 1) * 2 / 3) in static mode. The host alone creates them, and waits while the starting place is blocked."},
	{Name: "network.coop_enemies", Type: "integer", Default: 50, Env: "HALO_NET_COOP_ENEMIES", Live: false, Group: "Co-op", Comment: "Online co-op's extra enemies per player, a percentage: for each player past the first, each squad of enemies a level places gets this much of itself more (100: as many again; 25 to 200). PER PLAYER in co-op's Server Setup > Co-op Options writes its choice here."},
	{Name: "network.coop_enemies_multiplier", Type: "integer", Default: 2, Env: "HALO_NET_COOP_ENEMIES_MULTIPLIER", Live: false, Group: "Co-op", Comment: "Online co-op's shared static multiplier (2 to 32). Pickups are capped at 8 times their original count; extra vehicle growth uses two thirds of (multiplier - 1), rounded down. MULTIPLIER in co-op's Server Setup > Co-op Options writes its choice here."},
	{Name: "network.coop_public", Type: "boolean", Default: false, Env: "HALO_NET_COOP_PUBLIC", Live: false, Group: "Co-op", Comment: "Whether an online co-op game (Create Game > Internet, a SINGLEPLAYER map) starts as PUBLIC or, false, PRIVATE: Server Setup's LISTING in co-op, which writes its choice here."},
	{Name: "network.map_seed", Type: "boolean", Default: true, Env: "HALO_NET_MAP_SEED", Live: false, Group: "Map sharing", Comment: "Playing in another's game: help send its map to players who join without it, as a torrent's peers do (the pieces this machine has, at most network.map_seed_upload)."},
	{Name: "network.map_seed_upload", Type: "integer", Default: 256, Env: "HALO_NET_MAP_SEED_UPLOAD", Live: false, Group: "Map sharing", Comment: "Playing in another's game: the most kilobytes a second this machine sends of maps to other players (16 to 10240: 10 MB/s)."},
	{Name: "network.map_download", Type: "boolean", Default: true, Env: "HALO_NET_MAP_DOWNLOAD", Live: false, Group: "Map sharing", Comment: "Joining a game on a Custom Edition map this machine does not have: download it (and the resource maps it needs) from the game's players into custom_maps, if its host shares it (network.map_share); false leaves the game, saying which map is missing."},
	{Name: "network.client_timeout_seconds", Type: "integer", Default: 15, Env: "HALO_NET_CLIENT_TIMEOUT_SECONDS", Live: false, Group: "Network", Comment: "Seconds a host waits for a machine it hears nothing from before it drops it (5 to 300; the stock game's 15). Longer keeps players whose connection stalls (a browser tab in the background) at the cost of frozen players for longer when one really goes."},
	{Name: "network.block_mouse_aim_assist", Type: "boolean", Default: false, Env: "HALO_NET_BLOCK_MOUSE_AIM_ASSIST", Live: false, Group: "Network", Comment: "Host: disable optional mouse magnetism for mouse/keyboard players. Controllers and touch keep their own assist."},
	{Name: "network.public_lobby", Type: "boolean", Default: true, Env: "HALO_NET_PUBLIC_LOBBY", Live: false, Group: "Listing", Comment: "The server browser: public games are listed through the signalling brokers, and Join Game > Server Browser shows them. False lists no game of this machine's and shows none."},
	{Name: "network.online", Type: "boolean", Default: true, Env: "HALO_NET_ONLINE", Live: false, Group: "Listing", Comment: "Internet play: hosting makes an invite link (logged, and put on the clipboard) that lets whoever has it join over the internet; opening a link (or copying one before switching to the game) joins. Only people with the invite can join. Off keeps system link to the local network."},
	{Name: "server.master_publish_address", Type: "boolean", Default: false, Env: "HALO_SERVER_MASTER_PUBLISH_ADDRESS", Live: false, Group: "Listing", Comment: "Let the master servers give this server's address to players; false: only their reachability probe uses it."},
}
